use super::*;
use semio_framework_value::{ErasedSnapshotRetirement,admit_owned_retirement,owned_retirement_birth_bytes,native_decoding::{NativeDecodeAllocation,NativeDecodeAllocationPort,NativeDecodeRetirementRecipient}};
use std::mem::size_of_val;
#[derive(Clone,Copy)]
struct OriginalPages<'a>{pages:&'a[&'a[u8]],page_bytes:usize,identity:OriginalWireSourceIdentity}
impl RetainedWireByteSource for OriginalPages<'_>{fn original_source_identity(&self)->OriginalWireSourceIdentity{self.identity}fn byte_at(&self,index:usize)->Option<u8>{if index>=self.identity.extent{return None}self.pages.get(index/self.page_bytes)?.get(index%self.page_bytes).copied()}}
fn observe<T>(operation:impl FnOnce()->T)->(T,usize,usize){crate::test_allocation::observe_backing(operation)}
fn receipt(owner:&mut RetainedHistoryTransitionDecode,g:RetainedCloneGrant,born:usize,released:usize){let(issued,p)=owner.take_receipt().unwrap();assert_eq!(issued,g);assert!(p.fits(g));assert_eq!((born,released),(p.retained_capacity_bytes,p.released_bytes));}
pub(crate) fn close_original<T:semio_framework_value::retirement::RetireOwned>(original:T,control:&mut NativeDecodeControl<'_>,g:RetainedCloneGrant)->(usize,usize){let birth=owned_retirement_birth_bytes::<T>();assert!(birth<=g.maximum_capacity_bytes);control.charge(birth).unwrap();let(result,born,released)=observe(||admit_owned_retirement(original,g));let(mut owner,p)=result.map_err(|(error,_)|error).unwrap();assert!(p.fits(g));assert_eq!((born,released),(p.retained_capacity_bytes,p.released_bytes));let(mut births,mut releases)=(born,released);for _ in 0..100000{if owner.terminal_is_empty(){let bytes=size_of_val(owner.as_ref());assert!(bytes<=g.maximum_release_bytes);let(_,born,released)=observe(||drop(owner));assert_eq!((born,released),(0,bytes));return(births,releases+released)}let d=RetirementDemand{copy_bytes:owner.next_copy_byte_demand().unwrap(),capacity_bytes:owner.next_capacity_byte_demand(g.maximum_copy_bytes).unwrap(),release_bytes:owner.next_release_byte_demand().unwrap(),depth:owner.next_depth_demand().unwrap()};assert!(permits(g,d));control.charge(d.capacity_bytes).unwrap();let(step,born,released)=observe(||owner.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!((born,released),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=born;releases+=released}panic!("original transition recipient retirement failed to terminate")}
fn hex(value:&str)->Vec<u8>{value.as_bytes().chunks_exact(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect()}
#[test]
fn original_history_transition_native_pages_preserve_all_fields_same_ledger_and_paid_partial_custody(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let control_limit=law["control"]["maximumAllocationBytes"].as_u64().unwrap()as usize;let limits:HistoryReadLimits=serde_json::from_value(law["limits"].clone()).unwrap();let grant=&law["grant"];let n=|key:&str|grant[key].as_u64().unwrap()as usize;let g=RetainedCloneGrant{maximum_items:n("items"),maximum_copy_bytes:n("copyBytes"),maximum_capacity_bytes:n("capacityBytes"),maximum_release_bytes:n("releaseBytes"),maximum_depth:n("depth")};
 for row in law["transitions"].as_array().unwrap(){let body=hex(row["wireHex"].as_str().unwrap());let mut original=vec![0xaa];original.extend_from_slice(&body);let end=original.len();original.push(0xbb);for paged in[false,true]{let page_bytes=if paged{law["source"]["pageBytes"].as_u64().unwrap()as usize}else{original.len()};let pages=original.chunks(page_bytes).collect::<Vec<_>>();let identity=OriginalWireSourceIdentity{address:original.as_ptr()as usize,extent:original.len(),authority:if paged{Some((43,7))}else{None}};let source=OriginalPages{pages:&pages,page_bytes,identity};
 for cancellation in[0,1,7,31,100000]{let admitted=std::sync::atomic::AtomicUsize::new(0);let mut allocation=|request:NativeDecodeAllocation|{let owned=admitted.load(std::sync::atomic::Ordering::SeqCst);assert_eq!(request.owned_bytes,owned);assert!(request.bytes<=g.maximum_capacity_bytes);assert!(request.maximum_bytes<=control_limit);assert_eq!(request.next_owned_bytes,owned+request.bytes);admitted.store(request.next_owned_bytes,std::sync::atomic::Ordering::SeqCst);Ok(())};let port:&mut NativeDecodeAllocationPort<'_>=&mut allocation;let mut callback=|_:semio_framework_value::NativeDecodeProgress|true;let mut retirement=NativeDecodeRetirementRecipient::new();let mut control=NativeDecodeControl::new_forwarded(control_limit,&mut callback,port);control.install_retirement_recipient(&mut retirement).unwrap();let mut dictionary=RetainedSourceDictionary::new(&source);
  for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:1,..g}]{let(owner,born,released)=observe(||RetainedHistoryTransitionDecode::admit(&source,(1,end),limits,&control,denied).unwrap());assert!(owner.is_none());assert_eq!((born,released),(0,0))}
  let(owner,born,released)=observe(||RetainedHistoryTransitionDecode::admit(&source,(1,end),limits,&control,g).unwrap());assert_eq!((born,released),(0,0));let mut owner=owner.unwrap();let(step,born,released)=observe(||owner.step(&source,&dictionary,&mut control,g).unwrap());assert_eq!(step,RetainedHistoryTransitionStep::Blocked);assert_eq!((born,released),(0,0));receipt(&mut owner,g,0,0);
  for changed_identity in[OriginalWireSourceIdentity{address:identity.address+1,..identity},OriginalWireSourceIdentity{extent:identity.extent-1,..identity},OriginalWireSourceIdentity{authority:Some((43,8)),..identity}]{let changed=OriginalPages{identity:changed_identity,..source};let(result,born,released)=observe(||owner.step(&changed,&dictionary,&mut control,g));assert!(result.is_err());assert_eq!((born,released),(0,0));assert!(owner.receipt().is_none())}
  let mut foreign_callback=|_:semio_framework_value::NativeDecodeProgress|true;let mut foreign=NativeDecodeControl::new(control.maximum_bytes(),&mut foreign_callback);let(result,born,released)=observe(||owner.step(&source,&dictionary,&mut foreign,g));assert!(result.is_err());assert_eq!((born,released),(0,0));drop(foreign);
  let(mut births,mut releases)=(0,0);for _ in 0..cancellation{if owner.is_ready(){break}let d=owner.demands(&source,&control,g.maximum_copy_bytes).unwrap();for(axis,denied)in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g},RetainedCloneGrant{maximum_copy_bytes:0,..g},RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g},RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g}].into_iter().enumerate(){if axis==2&&d.copy_bytes==0||axis==3&&d.capacity_bytes==0||axis==4&&d.release_bytes==0{continue}let before=(owner.consumed_end(),control.owned_bytes());let(step,born,released)=observe(||owner.step(&source,&dictionary,&mut control,denied).unwrap());assert_eq!(step,RetainedHistoryTransitionStep::Blocked,"axis{axis} phase{} demand{d:?}",owner.phase);assert_eq!((born,released),(0,0));assert_eq!(before,(owner.consumed_end(),control.owned_bytes()));assert!(owner.receipt().is_none())}let(step,born,released)=observe(||owner.step(&source,&dictionary,&mut control,g).unwrap());assert_ne!(step,RetainedHistoryTransitionStep::Fault,"{:?}",owner.fault());assert_ne!(step,RetainedHistoryTransitionStep::Blocked);receipt(&mut owner,g,born,released);births+=born;releases+=released;assert_eq!(owner.source_identity(),identity)}
  if cancellation==100000{assert!(owner.is_ready());assert_eq!(owner.consumed_end(),end);let mut output=None;let(moved,born,released)=observe(||owner.take_ready_into(&mut output,g).unwrap());assert!(moved);assert_eq!((born,released),(0,0));receipt(&mut owner,g,0,0);let value=output.as_ref().unwrap();assert_eq!(value.id,row["id"].as_str().unwrap());assert_eq!(value.actor.as_str(),row["actor"].as_str().unwrap());let hlt=row["hlt"].as_array().unwrap();assert_eq!(value.hlt,(hlt[0].as_u64().unwrap(),hlt[1].as_u64().unwrap(),hlt[2].as_u64().unwrap()));assert_eq!(value.dependencies,row["dependencies"].as_array().unwrap().iter().map(|id|id.as_str().unwrap()).collect::<Vec<_>>());assert_eq!(value.payload,hex(row["payloadHex"].as_str().unwrap()));assert_eq!(value.observed.as_deref(),row["observed"].as_str());let(b,r)=close_original(output.take().unwrap(),&mut control,g);births+=b;releases+=r;}
  else{owner.cancel();for _ in 0..100000{if owner.partial_is_receivable(){let mut output=None;let(moved,born,released)=observe(||owner.take_partial_into(&mut output,g).unwrap());assert!(moved);receipt(&mut owner,g,born,released);let(b,r)=close_original(output.take().unwrap(),&mut control,g);births+=b;releases+=r;break}let(step,born,released)=observe(||owner.close_step(&source,&mut control,g).unwrap());assert_ne!(step,RetainedHistoryTransitionStep::Blocked);receipt(&mut owner,g,born,released);births+=born;releases+=released;}for _ in 0..16{if owner.terminal_is_empty(){break}let(step,born,released)=observe(||owner.close_step(&source,&mut control,g).unwrap());assert_ne!(step,RetainedHistoryTransitionStep::Blocked);receipt(&mut owner,g,born,released);births+=born;releases+=released;}}
  assert!(owner.terminal_is_empty());assert_eq!(births,releases);assert_eq!(control.owned_bytes(),admitted.load(std::sync::atomic::Ordering::SeqCst));let(_,born,released)=observe(||drop(owner));assert_eq!((born,released),(0,0));dictionary.cancel();dictionary.close_step(&source,g).unwrap();dictionary.take_receipt();assert!(dictionary.terminal_is_empty());drop(control);assert!(retirement.terminal_is_empty());
 }}}
 eprintln!("[DEBUG] Original Transition paged/contiguous formats preserve every native field, same ledger, independent full5 denials, actual paid partial/ready recipients and native birth/release conservation with terminalDrop0");
}
